import unittest
from app import summarize

class SummaryTest(unittest.TestCase):
    def test_total(self):
        result = summarize([2, 3])
        self.assertEqual(result, 5)
        self.assertIs(type(result), int)
    def test_empty(self):
        result = summarize([])
        self.assertEqual(result, 0)
        self.assertIs(type(result), int)

    def test_explicit_no_count(self):
        self.assertEqual(summarize([2, 3], include_count=False), 5)
        self.assertEqual(summarize([], include_count=False), 0)

    def test_include_count(self):
        self.assertEqual(
            summarize([2, 3], include_count=True),
            {"total": 5, "count": 2},
        )

    def test_include_count_empty(self):
        self.assertEqual(
            summarize([], include_count=True),
            {"total": 0, "count": 0},
        )

    def test_include_count_single_use_iterator(self):
        values = (value for value in [-2, 0, 3])
        self.assertEqual(
            summarize(values, include_count=True),
            {"total": 1, "count": 3},
        )

